final class PhoneCatchUp {
 static {String[][] words={{"Unfinished business","حكايات لم تكتمل"},{"Comfort rewatches","إعادة لأعمال تحبها"},{"Directors you love","مخرجون تحبهم"},{"Short tonight","مشاهدة قصيرة الليلة"},{"Smart lists","القوائم الذكية"},{"Catch me up","ذكّرني بالأحداث"},{"Dismiss catch-up","إخفاء التذكير"},{"You stopped at %s · %s","توقفت عند %s · %s"},{"No saved summary for this watched episode.","لا يوجد ملخص محفوظ لهذه الحلقة المشاهدة."},{"After %d days","بعد %d أيام"},{"Off","إيقاف"}};for(String[] w:words)Loc.AR.put(w[0],w[1]);}
 static void init(){}
 static int getThresholdDays(DataStore data){return Math.max(0,Math.min(365,data.prefs().optInt("catchUpDays",14)));}
 static void setThresholdDays(DataStore data,int days){data.pref("catchUpDays",Math.max(0,Math.min(365,days)));}
 static final class Recap {String key,returnId;SmartLists.Episode stopped;List<SmartLists.Episode> episodes;Recap(String key,String id,SmartLists.Episode stopped,List<SmartLists.Episode> eps){this.key=key;returnId=id;this.stopped=stopped;episodes=eps;}}
 static Recap build(SmartLists.Title title,long now,int days,String dismissed){if(title.movie||title.dropped||days<=0)return null;SmartLists.Episode stopped=null;for(SmartLists.Episode ep:title.episodes)if((ep.watched||ep.started)&&ep.lastViewed>0&&ep.lastViewed<=now&&(stopped==null||ep.lastViewed>stopped.lastViewed||ep.lastViewed==stopped.lastViewed&&SmartLists.before(stopped,ep)))stopped=ep;if(stopped==null||stopped.lastViewed>now-Math.max(1,Math.min(365,days))*SmartLists.DAY)return null;String token=stopped.lastViewed+":"+stopped.season+":"+stopped.episode;if(token.equals(dismissed))return null;List<SmartLists.Episode> watched=new ArrayList<>();for(SmartLists.Episode ep:title.episodes)if(ep.watched&&(ep.season==stopped.season&&ep.episode<=stopped.episode||ep.season>0&&ep.season<stopped.season))watched.add(ep);watched.sort((x,y)->{int s=Integer.compare(y.season,x.season);return s==0?Integer.compare(y.episode,x.episode):s;});if(watched.size()>2)watched=new ArrayList<>(watched.subList(0,2));Collections.reverse(watched);return watched.isEmpty()?null:new Recap(title.key,token,stopped,watched);}
 static JSONObject cachedMeta(DataStore data,JSONObject item){String id=PhoneCredits.imdb(item);if(id.isEmpty())return new JSONObject();String url="https://v3-cinemeta.strem.io/meta/"+(item.optBoolean("movie")?"movie":"series")+"/"+id+".json";File file=new File(new File(data.context.getCacheDir(),"credits"),NoirUi.sha(url)+".json");try{if(!file.isFile()||file.length()>2*1024*1024)return new JSONObject();JSONObject root=new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));JSONObject meta=root.optJSONObject("meta");return meta==null?root:meta;}catch(Exception ignored){return new JSONObject();}}
 static JSONObject cachedJson(DataStore data,String url){try{File file=new File(new File(data.context.getCacheDir(),"credits"),NoirUi.sha(url)+".json");return file.isFile()&&file.length()<=2*1024*1024?new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8)):new JSONObject();}catch(Exception ignored){return new JSONObject();}}
 static JSONArray cachedCast(DataStore data,JSONObject item){JSONArray cast=PhoneCredits.parseCinemeta(cachedMeta(data,item));if(!item.optBoolean("movie")){JSONObject show=cachedJson(data,"https://api.tvmaze.com/lookup/shows?imdb="+PhoneCredits.imdb(item));int id=show.optInt("id");if(id>0)try{File file=new File(new File(data.context.getCacheDir(),"credits"),NoirUi.sha("https://api.tvmaze.com/shows/"+id+"/cast")+".json");if(file.isFile()&&file.length()<=2*1024*1024)PhoneCredits.merge(cast,PhoneCredits.parseTvmaze(new JSONArray(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8))));}catch(Exception ignored){}}return cast;}
 static List<String> directors(JSONObject meta){List<String> values=new ArrayList<>();String names=PhoneCredits.names(meta.opt("director"));for(String name:names.split(","))if(!name.trim().isEmpty())values.add(name.trim());return values;}
 static String dismissKey(String group){return "catchUpDismiss:"+group;}
 static View card(MainActivity a,List<JSONObject> group,boolean compact){if(group==null||group.isEmpty())return null;init();String key=group.get(0).optString("group");SmartLists.Title title=SmartLists.read(group,a.browsingSettings(),Collections.emptyList(),i->false);Recap recap=build(title,System.currentTimeMillis(),getThresholdDays(a.data),a.data.prefs().optString(dismissKey(key)));if(recap==null)return null;
  LinearLayout card=a.column();card.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));android.graphics.drawable.GradientDrawable bg=MainActivity.bg(android.graphics.Color.rgb(26,25,27),a.dp(14));bg.setStroke(a.dp(1),android.graphics.Color.argb(95,228,192,132));card.setBackground(bg);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,a.dp(12),0,a.dp(8));card.setLayoutParams(cp);LinearLayout top=new LinearLayout(a);top.setGravity(Gravity.CENTER_VERTICAL);TextView name=a.text("Catch me up",compact?14:18,MainActivity.GOLD);name.setTypeface(null,Typeface.BOLD);top.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView dismiss=a.ui.small("✕",()->{a.data.pref(dismissKey(key),recap.returnId);card.setVisibility(View.GONE);a.renderKeep();},false);dismiss.setContentDescription(Loc.t("Dismiss catch-up"));top.addView(dismiss);card.addView(top);TextView stopped=a.text(Loc.f("You stopped at %s · %s",SmartLists.label(recap.stopped),SmartLists.ago(recap.stopped.lastViewed,System.currentTimeMillis(),Loc.arabic)),12,MainActivity.MUTED);stopped.setPadding(0,a.dp(6),0,a.dp(6));card.addView(stopped);
  for(SmartLists.Episode ep:recap.episodes){String summary=ep.summary.trim().isEmpty()?Loc.t("No saved summary for this watched episode."):android.text.Html.fromHtml(ep.summary,android.text.Html.FROM_HTML_MODE_LEGACY).toString().trim();TextView line=a.text(SmartLists.label(ep)+" · "+summary,compact?12:14,MainActivity.WHITE);line.setMaxLines(compact?3:4);line.setEllipsize(android.text.TextUtils.TruncateAt.END);line.setPadding(0,a.dp(6),0,0);card.addView(line);}
  if(!compact){long revision=a.renderRevision;a.data.images.execute(()->{JSONArray cast=cachedCast(a.data,group.get(0));List<Object[]> images=new ArrayList<>();for(JSONObject person:DataStore.objects(cast)){String url=person.optString("photo");File file=new File(new File(a.data.context.getFilesDir(),"discover"),NoirUi.sha(url)+".jpg");if(!url.isEmpty()&&file.isFile()){BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=4;Bitmap bitmap=BitmapFactory.decodeFile(file.getPath(),opts);if(bitmap!=null)images.add(new Object[]{person.optString("name"),bitmap});}if(images.size()>=5)break;}a.runOnUiThread(()->{if(a.isDestroyed()||revision!=a.renderRevision)return;LinearLayout photos=new LinearLayout(a);for(Object[] entry:images){ImageView image=new ImageView(a);image.setImageBitmap((Bitmap)entry[1]);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setContentDescription((String)entry[0]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(a.dp(40),a.dp(40));p.setMargins(0,a.dp(10),a.dp(8),0);photos.addView(image,p);}if(!images.isEmpty())card.addView(photos);});});}Motion.riseIn(card,0);return card;
 }
 static void addToUpNext(MainActivity a,LinearLayout host,List<JSONObject> group){View recap=card(a,group,true);if(recap!=null)host.addView(recap);}
 static View settingsRow(MainActivity a){init();int current=getThresholdDays(a.data);return PhoneExperience.rowView(a,"↺","Catch me up",(current==0?Loc.t("Off"):Loc.f("After %d days",current))+" · "+Loc.t("A short recap when you come back to a show"),()->{int[] values={0,7,14,30,60};String[] labels=new String[values.length];for(int n=0;n<values.length;n++)labels[n]=values[n]==0?Loc.t("Off"):Loc.f("After %d days",values[n]);int at=0;for(int n=0;n<values.length;n++)if(values[n]==current)at=n;new AlertDialog.Builder(a).setTitle(Loc.t("Catch me up")).setSingleChoiceItems(labels,at,(d,n)->{setThresholdDays(a.data,values[n]);d.dismiss();a.renderKeep();}).show();});}
}
